// @ts-strict-ignore
import * as React from "react";
import { useAuthState, useAuthDispatch } from "../../../auth/auth-context";
import { fetchProducts, fetchSession } from "../../../auth/auth-api";
import { IAuthDispatch, IAuthState } from "../../../types/auth-types";
import { useEffect } from "react";

export type AuthorizeProps = {
  auth: IAuthState;
  dispatch: IAuthDispatch;
};

/** For components that should be aware of auth but not require it */
const AuthAware = <T,>(Component: React.ComponentType<T & AuthorizeProps>) => {
  return function AwareComponent(props: T) {
    const state = useAuthState();
    const dispatch = useAuthDispatch();

    useEffect(() => {
      const checkInitialSession = async () => {
        fetchSession(dispatch);
      };

      if (!state.sessionFetched && !state.isFetchingSession) {
        checkInitialSession();
      }
    }, [state, dispatch]);

    useEffect(() => {
      if (!state.productsFetched && state.isLoggedIn) {
        fetchProducts(dispatch);
      }
    }, [state.productsFetched, state.isLoggedIn, dispatch]);

    return <Component auth={state} dispatch={dispatch} {...props} />;
  };
};

export default AuthAware;
